script:
frappe.ui.form.on("Polling Booth", {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button("Create Installation Task", function () {
                frappe.call({
                    method: "brihas_harish.brihas_harish.doctype.polling_booth.polling_booth.create_installation_task_manual",
                    args: {
                        name: frm.doc.name
                    },
                    callback: function (r) {
                        if (r.message) {
                            frappe.msgprint(`Installation Task <b>${r.message}</b> created!`);
                            frm.reload_doc();
                        }
                    }
                });
            }, "Quick Actions");
        }
    }
});

frappe.ui.form.on("Installation Task", {
    refresh(frm) {
        if (frappe.user_roles.includes("Field Operator")) {
            frm.set_df_property("supervisor", "read_only", 1);
        }
    }
});
